-- oracle: primary
-- Float literals meeting DECFLOAT; the DECFLOAT errors where a row is filtered; concatenation.
SELECT CHAR(DECFLOAT(1.5E-30)), CHAR(DECFLOAT(100E0)), CHAR(DECFLOAT(1, 34) + 1.5E-30), CHAR(CAST(0.1E0 AS DECFLOAT(16))), CHAR(DECFLOAT(2.5E0, 16)) FROM SYSIBM.SYSDUMMY1;
SELECT CHAR(CAST(1E10 AS DECFLOAT)), CHAR(DECFLOAT(1.0E0) * 3), CHAR(DECFLOAT(1) + CAST(0.1 AS REAL)) FROM SYSIBM.SYSDUMMY1;
SELECT 1 FROM SYSIBM.SYSDUMMY1 WHERE DECFLOAT('sNaN') + 1 > 0;
SELECT 1 FROM SYSIBM.SYSDUMMY1 WHERE DECFLOAT(1) / 0 > 0;
SELECT 1 FROM SYSIBM.SYSDUMMY1 WHERE CAST('abc' AS INTEGER) > 0;
SELECT 1 FROM SYSIBM.SYSDUMMY1 WHERE CAST('2026-13-01' AS DATE) > CURRENT DATE;
SELECT 1 FROM SYSIBM.SYSDUMMY1 WHERE DECFLOAT('9.999999999999999E384', 16) * 10 > 0;
SELECT 1 FROM SYSIBM.SYSDUMMY1 WHERE DECFLOAT('1E-398', 16) / 10 > 0;
SELECT 1 || 'x' FROM SYSIBM.SYSDUMMY1;
SELECT 'x' || 1.50 FROM SYSIBM.SYSDUMMY1;
SELECT 'x' || CURRENT DATE FROM SYSIBM.SYSDUMMY1;
SELECT 'x' || DECFLOAT('1.50') FROM SYSIBM.SYSDUMMY1;
SELECT 'x' || CAST(5 AS SMALLINT), 'x' || 0.5, 'x' || -0.5 FROM SYSIBM.SYSDUMMY1;
SELECT 1 + '1.5', '1.5' * 2, 1.0 + '1.5', 1.5E0 + '1', DECFLOAT(1) + '1.25' FROM SYSIBM.SYSDUMMY1;
SELECT CAST(1 AS SMALLINT) + CAST(1 AS SMALLINT), CAST(1 AS BIGINT) + 1, CAST(1 AS BIGINT) * 1.5, 1.5E0 + 1, CAST(1 AS REAL) + 1, CAST(1 AS REAL) + 1.5E0, DECFLOAT(1, 16) + 1.5E0 FROM SYSIBM.SYSDUMMY1;
SELECT CAST(1.5E0 AS CHAR(10)), CAST(-0.5 AS CHAR(5)), CAST(1 AS CHAR(1)), CAST('abcdef' AS CHAR(3)) FROM SYSIBM.SYSDUMMY1;
SELECT CAST(DATE('2026-11-05') AS CHAR(10)), CAST(DATE('2026-11-05') AS VARCHAR(20)), CAST(TIME('10:20:30') AS CHAR(8)), CAST(TIMESTAMP('2026-11-05-10.20.30.123456') AS CHAR(26)), CAST('2026-11-05' AS DATE), CAST('10.20.30' AS TIME) FROM SYSIBM.SYSDUMMY1;
SELECT CAST(TIMESTAMP('2026-11-05-10.20.30.123456') AS DATE), CAST(TIMESTAMP('2026-11-05-10.20.30.123456') AS TIME), CAST(DATE('2026-11-05') AS TIMESTAMP), CAST('2026-11-05' AS TIMESTAMP), CAST(TIME('10:20:30') AS TIMESTAMP) FROM SYSIBM.SYSDUMMY1;
SELECT CAST('abc' AS GRAPHIC(3) CCSID 13488), CAST('abc' AS VARGRAPHIC(5) CCSID 1200), CAST('abc' AS CHAR(3) CCSID 37), HEX(CAST('abc' AS CHAR(3) CCSID 1208)), HEX(CAST('abc' AS VARGRAPHIC(3) CCSID 1200)), HEX(CAST('abc' AS GRAPHIC(3) CCSID 13488)) FROM SYSIBM.SYSDUMMY1;
SELECT CAST('abc' AS CHAR(3) CCSID 500), CAST('abc' AS CHAR(3) CCSID 65535), CAST('abc' AS NCHAR(3)), CAST('abc' AS NVARCHAR(3)), CAST('abc' AS NCLOB(3)) FROM SYSIBM.SYSDUMMY1;
SELECT CAST(1 AS CHAR(3) CCSID 1200) FROM SYSIBM.SYSDUMMY1;
SELECT CAST('abc' AS GRAPHIC(3) CCSID 37) FROM SYSIBM.SYSDUMMY1;
SELECT CAST('abc' AS VARCHAR(3) FOR SBCS DATA), CAST('abc' AS VARCHAR(3) FOR MIXED DATA), CAST('abc' AS VARCHAR(3) FOR BIT DATA) FROM SYSIBM.SYSDUMMY1;
SELECT COALESCE(1, 1.5), COALESCE(CAST(1 AS SMALLINT), CAST(2 AS BIGINT)), COALESCE('a', 'bcd'), COALESCE(1, 2.5E0), COALESCE(DECFLOAT(1, 16), 2), COALESCE(1, '2') FROM SYSIBM.SYSDUMMY1;
SELECT CASE WHEN 1 = 1 THEN 1 ELSE 2.55 END, CASE WHEN 1 = 1 THEN 'a' ELSE 'bcd' END, CASE WHEN 1 = 0 THEN 1 ELSE 2.5E0 END, CASE WHEN 1 = 1 THEN 1 ELSE '2' END FROM SYSIBM.SYSDUMMY1;
SELECT CASE WHEN 1 = 1 THEN 1 ELSE CURRENT DATE END FROM SYSIBM.SYSDUMMY1;
SELECT CASE WHEN 1 = 1 THEN BX'01' ELSE 'a' END FROM SYSIBM.SYSDUMMY1;
SELECT 1 FROM SYSIBM.SYSDUMMY1 WHERE 1 = '1';
SELECT 1 FROM SYSIBM.SYSDUMMY1 WHERE 1 = 'x';
SELECT 1 FROM SYSIBM.SYSDUMMY1 WHERE CURRENT DATE = 1;
SELECT 1 FROM SYSIBM.SYSDUMMY1 WHERE BX'01' = 1;
SELECT 1 FROM SYSIBM.SYSDUMMY1 WHERE BX'C1' = 'A';
